L4_1.m_Pos = "R"
L4_1.m_Talk_KOREA = "네. 그레모리라는 이름을 쓰는 바는 이 가게 하나뿐입니다."
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "はい。グレモリーを名前に使っているお店はここしかありません。"
L4_1.m_Talk_ENG = "Yes. This is the only bar around here that's named Gremory."
L4_1.m_Talk_TWN = "對，這裡叫葛茉莉的酒吧，就只有這麼一間。"
L4_1.m_Talk_THA = "ใช่ บาร์แถวนี้ก็มีชื่อเกรมอรีอยู่ที่เดียวนั่นแหละ"
L4_1.m_Talk_VTN = "Đúng thế. Đây là quán bar duy nhất gần đây có tên là Gremory."
L4_1.m_Talk_SCN = "是的。叫葛茉莉的酒吧只有这一家。"
L4_1.m_Talk_DEU = "Ja. Dies ist die einzige Bar hier, die Gremory heißt."
L4_1.m_Talk_FRA = "Oui. C'est le seul bar du coin avec « Gremory » dans le nom."
