L8_1.m_Talk_KOREA = "하, 하지만 음침하지 않고 입구부터 알록달록하지 않나요?"
L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "で、でも薄暗い感じもないし、入り口も鮮やかです。"
L8_1.m_Talk_ENG = "B-but it doesn't look gloomy at all... The entrance looks too colorful."
L8_1.m_Talk_TWN = "可…可是它一點也不灰暗，從大門口就很色彩繽紛欸？"
L8_1.m_Talk_THA = "ตะ-แต่มันดูไม่หม่นไม่หมองเลยนะคะ... ทางเข้าสีสันสดใสมาก"
L8_1.m_Talk_VTN = "N-nhưng nó trông không có vẻ u ám chút nào... Lối vào trông quá chói mắt."
L8_1.m_Talk_SCN = "但、但是一点也不阴森，从大门口看装饰很是绚丽啊？"
L8_1.m_Talk_DEU = "A-aber sie sieht gar nicht düster aus ... Der Eingang ist zu bunt."
L8_1.m_Talk_FRA = "M-Mais cet endroit n'a rien de sordide ! Et c'est quoi, tous ces néons à l'entrée ?"
