L10_1.m_CharStrID = "HOSTAGE_NPC_POSIONRAT_RELEASED"
L10_1.m_Talk_KOREA = "예? 그러면 무슨 문제라도 되는 건가요?"
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "え？　それだと何か問題でもあるんですか？"
L10_1.m_Talk_ENG = "Huh? Is that a problem?"
L10_1.m_Talk_TWN = "嗯？這有什麼問題嗎？"
L10_1.m_Talk_THA = "หา? นั่นใช่ประเด็นเหรอ?"
L10_1.m_Talk_VTN = "Ủa? Vậy cũng có vấn đề à?"
L10_1.m_Talk_SCN = "那？那样有什么问题吗？"
L10_1.m_Talk_DEU = "Huch? Ist das ein Problem?"
L10_1.m_Talk_FRA = "Euh ? C'est quoi, le problème ?"
L11_1 = {}
L11_1.m_CutScenKey_Talk = "GREMORY_ACT1_INTERLUDE1@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 3800104
L11_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L11_1.m_Talk_KOREA = "아, 아무것도 아니에요! 직접 안내해 주셔서 감사합니다!"
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "な、なんでもありません！　ここまで案内してくれてありがとうございます！"
L11_1.m_Talk_ENG = "N-never mind. Thank you for showing me the way here."
L11_1.m_Talk_TWN = "喔，沒有啦！謝謝你替我帶路！"
L11_1.m_Talk_THA = "ชะ-ช่างเถอะค่ะ ยังไงก็ขอบคุณที่บอกทางนะคะ"
L11_1.m_Talk_VTN = "T-thôi được rồi. Cảm ơn đã chỉ đường."
L11_1.m_Talk_SCN = "没、没什么！感谢你亲自带我来！"
L11_1.m_Talk_DEU = "E-egal. Danke, dass Sie mir den Weg hierher gezeigt haben."
L11_1.m_Talk_FRA = "N-Non, rien. Merci de m'avoir guidée jusqu'ici !"
L12_1 = {}
L12_1.m_CutScenKey_Talk = "GREMORY_ACT1_INTERLUDE1@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 3800104
L12_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "HOSTAGE_NPC_POSIONRAT_RELEASED"
L12_1.m_Talk_KOREA = "감사는요. 제 목숨을 구해주신 은인이신데 이 정돈 당연히 해 드려야죠."
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "いえいえ。命を救ってくれた恩人なので、このくらい当然です。"
L12_1.m_Talk_ENG = "You're welcome. You saved my life! It's the least I can do."
L12_1.m_Talk_TWN = "沒什麼好謝的，你可是我的救命恩人，這點小忙是我應該幫的！"
L12_1.m_Talk_THA = "ด้วยความยินดี เธอช่วยชีวิตฉันไว้นี่! อย่างน้อยฉันก็ทำได้แค่นั้นแหละ"
L12_1.m_Talk_VTN = "Không có gì. Cô đã cứu mạng tôi! Ít nhất tôi cũng nên làm thế!"
L12_1.m_Talk_SCN = "不用谢。你是我的救命恩人，这点小事不足挂齿。"
L12_1.m_Talk_DEU = "Gern geschehen. Sie haben mein Leben gerettet! Das ist das Mindeste, was ich tun kann."
L12_1.m_Talk_FRA = "Y'a pas de quoi. Vous m'avez sauvé la vie, c'était la moindre des choses !"
