L20_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L20_1.m_Talk_KOREA = "하지만 펜듈럼은 이곳에서도 여전히 반응하고 있어요."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "でもペンデュラムはここでも相変わらず反応しています。"
L20_1.m_Talk_ENG = "But my pendulum is reacting to this place as well."
L20_1.m_Talk_TWN = "不過鐘擺對這裡也有反應！"
L20_1.m_Talk_THA = "แต่ลูกตุ้มฉันก็มีปฏิกริยากับที่นี่ด้วย"
L20_1.m_Talk_VTN = "Nhưng con lắc của mình cũng đang phản ứng với nơi này."
L20_1.m_Talk_SCN = "但钟摆离这么远都出现了反应。"
L20_1.m_Talk_DEU = "Aber mein Pendel reagiert auf diesen Ort."
L20_1.m_Talk_FRA = "Mais mon pendule, lui, réagit bel et bien."
L21_1 = {}
L21_1.m_CutScenKey_Talk = "GREMORY_ACT1_INTERLUDE1@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 3800104
L21_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L21_1.m_Talk_KOREA = "그렇다는 건… 멀리서도 반응할 정도로 강력한 악마라는 뜻이겠죠."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "ということは……遠くからでも反応するような強力な悪魔ということでしょう。"
L21_1.m_Talk_ENG = "That means... the devil is so powerful that its presence can be detected even from far away."
L21_1.m_Talk_TWN = "意思就是…這裡的魔鬼強到，在很遠的地方也感應得到吧！"
L21_1.m_Talk_THA = "ก็แปลว่า... ปีศาจที่นี่ฤทธิ์มากจนสัมผัสตัวตนได้แต่ไกลเลยสินะ"
L21_1.m_Talk_VTN = "Điều đó có nghĩa là... con ác ma này mạnh đến mức con lắc có thể phát hiện sự hiện diện của nó từ chỗ xa thế này."
L21_1.m_Talk_SCN = "也就是说……是离得很远也能感应得到的强大恶魔。"
L21_1.m_Talk_DEU = "Das heißt, der Teufel ist so mächtig, dass seine Anwesenheit sogar aus der Ferne wahrgenommen werden kann."
L21_1.m_Talk_FRA = "Ce qui signifie... qu'un diable a élu repaire à cet endroit. Un diable suffisamment puissant pour être détecté depuis l'autre côté de la rue."
L22_1 = {}
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 3800104
