L23_1 = {}
L23_1.m_CutScenKey_Talk = "GREMORY_ACT1_INTERLUDE1@23#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 3800104
L23_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L23_1.m_Talk_KOREA = "……정말 저 혼자서도 괜찮은 거겠죠?"
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "……本当に私一人でも大丈夫でしょうか？"
L23_1.m_Talk_ENG = "... I can do this alone, right?"
L23_1.m_Talk_TWN = "……我自己一個人真的可以嗎？"
L23_1.m_Talk_THA = "... ฉันจัดการเองคนเดียวได้ใช่มั้ยนะ?"
L23_1.m_Talk_VTN = "...Mình có thể hoàn thành nhiệm vụ một mình không đây?"
L23_1.m_Talk_SCN = "我……能靠自己解决吗？"
L23_1.m_Talk_DEU = "Das schaffe ich bestimmt alleine ... oder?"
L23_1.m_Talk_FRA = "... Suis-je vraiment de taille pour ce travail ?"
L24_1 = {}
L24_1.m_CutScenKey_Talk = "GREMORY_ACT1_INTERLUDE1@24#Talk"
L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 3800104
L24_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L24_1.m_Talk_KOREA = "지상에 올라온 악마들은 교활해서 쉽게 정체를 드러내지 않는다고 하던데……."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "地上にでて来た悪魔たちは狡猾で簡単には正体を現さないそうですが……"
L24_1.m_Talk_ENG = "I was told devils on earth are cunning and rarely expose themselves..."
L24_1.m_Talk_TWN = "我聽說地上的魔鬼都很狡猾，不會輕易露出真面目……"
L24_1.m_Talk_THA = "ได้ยินว่าปีศาจบนโลกทั้งเจ้าเล่ห์แล้วก็ไม่ค่อยเปิดเผยตัวกัน..."
L24_1.m_Talk_VTN = "Mọi người đều nói với mình rằng ác ma trên mặt đất đều xảo trá và hiếm khi lộ nguyên hình.."
L24_1.m_Talk_SCN = "跑到地面上来的恶魔通常都很狡猾，不会轻易露出真面目……"
L24_1.m_Talk_DEU = "Mir wurde gesagt, dass Teufel auf Erden listig seien und sich selten erkenntlich geben ..."
L24_1.m_Talk_FRA = "Il paraît que les diables remontés à la surface sont si rusés qu'il n'est pas facile de les percer à jour..."
L25_1 = {}
L25_1.m_CutScenKey_Talk = "GREMORY_ACT1_INTERLUDE1@25#Talk"
L25_1.m_CutScenProcessKey = 25
L25_1.m_CutScenID = 3800104
L25_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L25_1.m_Talk_KOREA = "악마를 직접 본 적도 없는 제가 과연 악마를 찾아낼 수 있을지 걱정이네요."
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "悪魔を直接見たこともない私が、果たして悪魔を見つけられるか心配です。"
L25_1.m_Talk_ENG = "I've never seen a devil before. I don't know if I can even find one."
L25_1.m_Talk_TWN = "我又沒親眼看過魔鬼，真的有辦法揪出魔鬼來嗎？"
L25_1.m_Talk_THA = "ฉันไม่เคยเห็นปีศาจมาก่อนหรอก ไม่รู้ด้วยซ้ำว่าจะได้เจอสักตนมั้ย"
L25_1.m_Talk_VTN = "Trước đây mình còn chưa thấy ác ma nào thực sự. Mình không biết liệu mình có thể tìm thấy chúng không nữa."
L25_1.m_Talk_SCN = "我也没有亲眼见过恶魔的样子，真的有办法找出恶魔来吗？"
L25_1.m_Talk_DEU = "Ich habe noch nie einen Teufel gesehen. Ich weiß nicht, ob ich überhaupt einen finden kann."
L25_1.m_Talk_FRA = "Est-ce que je vais réussir à le démasquer, moi qui n'ai jamais vu de diable de ma vie ?"
L26_1 = {}
L26_1.m_CutScenKey_Talk = "GREMORY_ACT1_INTERLUDE1@26#Talk"
L26_1.m_CutScenProcessKey = 26
L26_1.m_CutScenID = 3800104
L26_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L26_1.m_Talk_KOREA = "분명 쉽지 않겠지만… 시간은 충분하니 차근차근 찾아보면 되겠죠!"
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "きっと簡単ではないと思いますが……時間は十分あるので、慎重に探していけば大丈夫でしょう！"
L26_1.m_Talk_ENG = "It won't be easy, but I've got plenty of time. I'll take one step at a time!"
L26_1.m_Talk_TWN = "感覺就是個大難題…反正時間很充裕，我就慢慢地找吧！"
L26_1.m_Talk_THA = "มันไม่ง่ายแน่ๆ แต่ฉันมีเวลาเยอะแยะ ฉันจะค่อยๆ ทำไปทีละก้าวแล้วกัน!"
L26_1.m_Talk_VTN = "Sẽ không dễ dàng đâu, nhưng mình còn nhiều thời gian. Mình sẽ đi từng bước một!"
L26_1.m_Talk_SCN = "感觉这次的任务一定很艰难……呃啊，没关系，妮可！反正有很多时间，慢慢找吧！"
L26_1.m_Talk_DEU = "Es wird nicht einfach, aber ich habe viel Zeit. Eins nach dem anderen!"
L26_1.m_Talk_FRA = "Ce ne sera pas facile... Mais au moins, ce n'est pas le temps qui manque. Un pas à la fois !"
