L41_1.m_Pos = L42_1
L42_1 = "휴, 생각보다 찾기 쉬웠네요. 애써 조사할 필요도 없었군요."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "ふう、思ったよりすぐに見つかりましたね。\nわざわざ調査する必要もありませんでした。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Whew, that was easier than I thought. I didn't even have to look."
L41_1.m_Talk_ENG = L42_1
L42_1 = "呼～得來全不費工夫呢！根本不需要找得那麼辛苦嘛～"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ฟู่ ง่ายกว่าที่คิดแฮะ ฉันไม่ต้องมองด้วยซ้ำ"
L41_1.m_Talk_THA = L42_1
L42_1 = "Chà, dễ hơn mình tưởng. Mình thậm chí còn chẳng phải nhìn lấy một cái."
L41_1.m_Talk_VTN = L42_1
L42_1 = "呼，比想象中的简单呢。不用费心去调查了。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Puh, das war einfacher, als ich dachte. Ich musste nicht einmal investigieren."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Pfiouh, c'était plus facile que prévu. Je n'ai même pas eu besoin de mener l'enquête."
L41_1.m_Talk_FRA = L42_1
