L4_1 = "酔って寝言言ってる場合ではないぞ！\n人間の女が吾輩を退治しようとしておる！"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Wake up and get sober, quick! Some human girl is trying to exorcise me!"
L3_1.m_Talk_ENG = L4_1
L4_1 = "現在不是發酒瘋的時候！有個莫名其妙的人類女生想打死我啦！"
L3_1.m_Talk_TWN = L4_1
L4_1 = "รีบตื่นรีบสร่างได้แล้ว! มีมนุษย์เด็กมันจะมาทำพิธีไล่ผีใส่ข้า!"
L3_1.m_Talk_THA = L4_1
L4_1 = "Dậy đi! Một con nhóc loài người đang cố gắng trừ tà ta này!"
L3_1.m_Talk_VTN = L4_1
L4_1 = "现在可不是醉酒说梦话的时候！有个陌生人类在打我！"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Wach auf und werde nüchtern, schnell! Dieses Menschenmädchen versucht, mich auszutreiben!"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Tu vas te réveiller, oui ? Décuve un peu, cette tarée essaie de m'assassiner !"
L3_1.m_Talk_FRA = L4_1
