L6_1 = "UNIT_SERIOUS"
L5_1.m_Face = L6_1
L5_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L6_1 = "C"
L5_1.m_Pos = L6_1
L6_1 = "때리는 게 아니에요! 신성한 정화의식이라고요! 순순히 지옥으로 돌아가 주시죠!"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "ただ叩いているわけではありません！　神聖なる浄化儀式です！　大人しく地獄に帰ってください！"
L5_1.m_Talk_JPN = L6_1
L6_1 = "I'm not beating you! This is a sacred purging ritual! Please go back to Hell when I ask nicely!"
L5_1.m_Talk_ENG = L6_1
L6_1 = "我沒有打你！這是神聖的淨化儀式！你乖乖地回到地獄去吧！"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ฉันไม่ได้ทำร้ายคุณนะคะ! นี่เป็นพิธีกรรมชำระล้างศักดิ์สิทธิ์! ช่วยกลับไปนรกในตอนที่ฉันยังขอกันดีๆ ด้วยค่ะ!"
L5_1.m_Talk_THA = L6_1
L6_1 = "Ta không đánh ngươi nhé! Đây là nghi thức thanh tẩy thần thánh! Hãy quay về Địa Ngục khi ta còn nói chuyện tử tế!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "我可不是在打你！这是神圣的净化仪式！还是乖乖回到地狱去吧！"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Ich schlage dich nicht! Das ist ein heiliges Reinigungsritual! Bitte geh zurück in die Hölle, solange ich noch nett frage!"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Ce n'est pas un assassinat, c'est un rituel de purification ! Soyez gentille et retournez en enfer, d'accord ?"
L5_1.m_Talk_FRA = L6_1
