L10_1 = "い、いじめないでください。このキャンディ、全部あげるから！"
L9_1.m_Talk_JPN = L10_1
L10_1 = "P-please don't hurt me. I'll give you my candy."
L9_1.m_Talk_ENG = L10_1
L10_1 = "別打我，我給你糖果！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ยะ-อย่าทำหนูนะ หนูให้ลูกกวาดหมดเลยเอ้า"
L9_1.m_Talk_THA = L10_1
L10_1 = "Đ-đừng làm tôi đau. Tôi sẽ cho cô kẹo."
L9_1.m_Talk_VTN = L10_1
L10_1 = "请、请不要伤害我。我可以给你糖吃。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "B-bitte tu mir nicht weh. Ich gebe dir meine Süßigkeiten."
L9_1.m_Talk_DEU = L10_1
L10_1 = "N-Ne me fais pas de mal, s'il te plaît ! Je partagerai mes bonbons avec toi !"
