L28_1 = "UNIT_LAUGH"
L27_1.m_Face = L28_1
L28_1 = "GREMORY_BAR_NULL_QM"
L27_1.m_CharStrID = L28_1
L28_1 = "C"
L27_1.m_Pos = L28_1
L28_1 = "m_CharScale"
L29_1 = {}
L30_1 = 1.3
L31_1 = 1.3
L29_1[1] = L30_1
L29_1[2] = L31_1
L27_1[L28_1] = L29_1
L28_1 = "m_CharScaleTime"
L27_1[L28_1] = 0.01
L28_1 = "많이 피곤했던 모양이네. 면접 보는 도중에 잠들어 버리다니 말이야."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "ずいぶんお疲れだったみたいね。面接の途中で眠ってしまうなんて。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "You must have been tired. You fell asleep during your interview."
L27_1.m_Talk_ENG = L28_1
L28_1 = "你是不是太累了？剛剛面試到一半就睡著了。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "เธอคงจะเหนื่อยน่ะ สัมภาษณ์อยู่ดีๆ ก็หลับไปเฉยเลย"
L27_1.m_Talk_THA = L28_1
L28_1 = "Chắc là cô mệt lắm. Cô đã ngủ gật trong khi đang được phỏng vấn."
L27_1.m_Talk_VTN = L28_1
L28_1 = "你应该很疲惫吧。竟然在面试的过程中睡着了。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Du musst müde gewesen sein. Du bist während deines Vorstellungsgesprächs eingeschlafen."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Hé bien, tu devais vraiment être épuisée pour t'endormir en plein milieu de ton entretien."
L27_1.m_Talk_FRA = L28_1
