L31_1 = "GREMORY_ACT1_INTERLUDE1@80#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 80
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 3800104
L30_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_Face = "UNIT_SURPRISE"
L31_1 = "THEMA_GREMORY"
L30_1.m_StartBGMFileName = L31_1
L31_1 = "FX_CUTSCEN_NOISE_RUSTLE_04"
L30_1.m_StartFXSoundName = L31_1
L30_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L30_1.m_Pos = "R"
L31_1 = "m_Crash"
L30_1[L31_1] = 20
L31_1 = "앗? 제가 졸았나요? 죄송해요!"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "あっ、居眠りしちゃってましたか？　すみません！"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Ah, did I? I'm sorry!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "蛤？我睡著了嗎？真是不好意思！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "อ๊ะ จริงเหรอคะ? ขอโทษค่ะ!"
L30_1.m_Talk_THA = L31_1
L31_1 = "A, thế ạ? Em xin lỗi!"
L30_1.m_Talk_VTN = L31_1
L31_1 = "什么？我睡着了？抱歉！"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ach, bin ich das? Das tut mir leid!"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Oh ? V-Vraiment ? Je suis désolée !"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "GREMORY_ACT1_INTERLUDE1@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3800104
L31_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "GREMORY_BAR_NULL_QM"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "L"
L32_1 = "이력서는 잘 봤어."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "履歴書は確認したわ。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "I read your resume."
L31_1.m_Talk_ENG = L32_1
L32_1 = "我看過你的履歷表了。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ฉันอ่านประวัติเธอแล้วนะ"
L31_1.m_Talk_THA = L32_1
L32_1 = "Tôi đã đọc sơ yếu lý lịch của cô."
L31_1.m_Talk_VTN = L32_1
L32_1 = "我看过你的简历了。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Ich habe deinen Lebenslauf gelesen."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Bon, j'ai bien lu ton CV."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "GREMORY_ACT1_INTERLUDE1@82#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 82
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3800104
L32_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "GREMORY_BAR_NULL_QM"
L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "L"
L33_1 = "샤레이드 출신이라… 거긴 콧대 높은 졸부들만 남아 있는 줄 알았는데…"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "シャレード出身ね……あそこは成金しか住んでないと思ってたのに……"
L32_1.m_Talk_JPN = L33_1
L33_1 = "You're from Charade, huh? I thought only arrogant upstarts lived there now."
L32_1.m_Talk_ENG = L33_1
L33_1 = "上面說你來自查雷德…據我所知，那裡應該都是些眼睛長在頭頂上的的暴發戶吧…"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เธอมาจากชาเรดเหรอ? นึกว่าตอนนั้นมีแต่พวกเศรษฐีใหม่ที่จองหองซะอีก"
L32_1.m_Talk_THA = L33_1
L33_1 = "Cô đến từ Charade, phải không? Tôi tưởng bây giờ chỉ có những kẻ mới nổi kiêu ngạo mới sống ở đó."
L32_1.m_Talk_VTN = L33_1
L33_1 = "来自查雷德啊……我还以为那里只剩下眼高于顶的暴发户呢……"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Du bist aus Charade, was? Ich dachte, dort leben jetzt nur arrogante Neureiche."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Tu viens de Charade, n'est-ce pas ? Je croyais que c'était une ville de bobos arrogants..."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "GREMORY_ACT1_INTERLUDE1@83#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3800104
L33_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "UNIT_LAUGH"
L33_1.m_Face = L34_1
L34_1 = "GREMORY_BAR_NULL_QM"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "L"
L34_1 = "그런 곳에서 귀하게 자란 아가씨가 바텐더 일을 하려고 이렇게 험한 도시까지 내려오다니, 오래 살고 볼 일인걸?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "そんな所で育ったお嬢様が、\nバーテンダーの仕事をするためにこんな物騒な都市まで来るなんて、\n長生きしてみるものね。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "A girl from a rich town comes all the way to this sinful city to work as a bartender? You live and learn, I guess."
L33_1.m_Talk_ENG = L34_1
L34_1 = "你一個嬌生慣養的千金大小姐，竟然為了想當調酒師，跑到這麼危險的都市來，還真是稀奇呢？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "เด็กหญิงจากเมืองคนรวยมาถึงเมืองคนบาปนี่เพื่อทำงานเป็นบาร์เทนเดอร์งั้นเหรอ? ชีวิตเจอเรื่องไม่ดีมาสินะ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Một cô gái đến từ một thị trấn giàu có lại cất công tới tận thành phố tội lỗi này để xin làm nhân viên pha chế sao? Tôi đoán là cô muốn trải nghiệm cuộc sống nhỉ."
L33_1.m_Talk_VTN = L34_1
L34_1 = "在那里娇生惯养的大小姐竟然也想要成为调酒师，还亲自来到了这里。真是令人意外啊？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Ein Mädchen aus einer reichen Stadt kommt den ganzen Weg in diese sündige Stadt, um als Barkeeperin zu arbeiten? Wo gibt es denn so was?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Qu'est-ce qu'une fille de la haute vient chercher en essayant de travailler comme barmaid dans ce taudis ? On aura tout vu..."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "GREMORY_ACT1_INTERLUDE1@84#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 84
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3800104
L34_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_Face = "UNIT_SURPRISE"
L34_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L34_1.m_Pos = "R"
L35_1 = "m_Crash"
L34_1[L35_1] = 20
L35_1 = "아, 실은 집안에서도 걱정을 많이 했거든요. 저 같은 애가 퇴마… 가 아니라, 술집에서 일한다고요."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "はい、実は家族もとても心配していたんです。\n私みたいな子が退魔……じゃなくて、酒場で働きたがるなんてって。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Oh, actually, my family was worried about the same. They didn't want me to become an exor—a bartender."
L34_1.m_Talk_ENG = L35_1
L35_1 = "喔，其實家裡知道我要當驅魔…不是，是在酒吧上班的時候也很擔心我呢！"
L34_1.m_Talk_TWN = L35_1
L35_1 = "อ๋อ จริงๆ บ้านฉันก็กังวลเรื่องเดียวกันเลยค่ะ พวกเขาไม่อยากให้ฉันเป็นนักปร... บาร์เทนเดอร์ค่ะ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Dạ, thực ra thì gia đình em cũng lo lắng như vậy. Họ không muốn em trở thành một thầy trừ — một nhân viên pha chế."
L34_1.m_Talk_VTN = L35_1
L35_1 = "啊，其实家里边也很担心。像我这样的驱魔……不，我在酒吧工作这件事。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Oh, ja, meine Familie war besorgt um mich. Sie wollten nicht, dass ich eine Exor- äh, eine Barkeeperin werde."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Ah, euh... À vrai dire, mes parents se sont beaucoup inquiétés de mon départ. Ils ne voulaient vraiment pas que je devienne exor... je veux dire, barmaid."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "GREMORY_ACT1_INTERLUDE1@85#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 85
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 3800104
L35_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "UNIT_LAUGH"
L35_1.m_Face = L36_1
L35_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L35_1.m_Pos = "R"
L36_1 = "그래도 제가 남들보다 좀 빨리 배우고 익히는 타입이라 재능을 인정받았어요!"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "でも私は周りより飲み込みが早いタイプなので、才能を認められたんです！"
L35_1.m_Talk_JPN = L36_1
L36_1 = "But I'm a quick learner. I finished the course quicker than the others!"
L35_1.m_Talk_ENG = L36_1
L36_1 = "不過家人也都認同我的學習能力比別人好！"
L35_1.m_Talk_TWN = L36_1
L36_1 = "แต่ฉันเรียนรู้เร็วนะคะ ฉันเรียนจบเร็วกว่าคนอื่นอีกค่ะ!"
L35_1.m_Talk_THA = L36_1
L36_1 = "Nhưng em học hỏi nhanh lắm. Em đã hoàn thành khóa học nhanh hơn những người khác!"
L35_1.m_Talk_VTN = L36_1
L36_1 = "不过我的学习能力很强，学东西和熟悉新工作都要比别人来得快！"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Aber ich lerne schnell. Ich habe den Kurs schneller beendet als die anderen!"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Mais j'apprends vite, vous savez ? Et puis je m'adapte très facilement."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "GREMORY_ACT1_INTERLUDE1@86#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 86
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3800104
L36_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "GREMORY_BAR_NULL_QM"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "L"
L37_1 = "그래? 잘됐네. 여기도 마침 그런 인재가 필요하던 참이었거든."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "そうなの？　よかったわ。\nこの店にもちょうどそういう人材が必要だったところなのよ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Did you? Good, I could use someone like you."
L36_1.m_Talk_ENG = L37_1
L37_1 = "是嗎？那太好啦，我們店裡正好需要這種人才！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "จริงเหรอ? ดีเลย แบบเธอใช้การได้แน่"
L36_1.m_Talk_THA = L37_1
L37_1 = "Vậy sao? Tốt, tôi thích tuyển người giống như cô."
L36_1.m_Talk_VTN = L37_1
L37_1 = "是吗？那很好。这里也正好需要你这样的人才。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Hast du das? Gut, ich könnte jemanden wie dich gebrauchen."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Vraiment ? On dirait que tu pourrais m'être utile, dans ce cas."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
