L38_1 = "난 여기 가게 주인. 편하게 주인님이라고 불러."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "アタシはここの店主。アタシのことは気軽にご主人様と呼んでね。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "I own this bar. You can call me Mistress."
L37_1.m_Talk_ENG = L38_1
L38_1 = "我是這家店的主人，你就稱呼為我主人吧！"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ฉันเป็นเจ้าของบาร์นี้ เรียกฉันนายหญิงก็ได้"
L37_1.m_Talk_THA = L38_1
L38_1 = "Tôi là chủ quán bar này. Cô có thể gọi tôi là Cô Chủ."
L37_1.m_Talk_VTN = L38_1
L38_1 = "我是这间酒吧的主人。你就叫我……主人就可以啦。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Ich besitze diese Bar. Du kannst mich Herrin nennen."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Je suis la propriétaire de ce bar. Tu peux m'appeler « Maîtresse »."
L37_1.m_Talk_FRA = L38_1
