L40_1 = "우와, 순진하기도 하지."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "あらぁ、なんて純粋な子かしら。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Wow, you're so trusting, aren't you?"
L39_1.m_Talk_ENG = L40_1
L40_1 = "哇～怎麼這麼單純～"
L39_1.m_Talk_TWN = L40_1
L40_1 = "เธอเป็นพวกเชื่อคนง่ายใช่มั้ยเนี่ย?"
L39_1.m_Talk_THA = L40_1
L40_1 = "Chà, cô có vẻ đáng tin cậy đấy nhỉ?"
L39_1.m_Talk_VTN = L40_1
L40_1 = "哇啊，真是个单纯的孩子呢。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Wow, du bist aber naiv."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Ha ha. Tu crois tout ce qu'on te dit, hein ?"
