L42_1 = "주인님은 농담이야. 편하게 그레모리 씨라고 부르면 돼."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "ご主人様は冗談よ。グレモリーさんでいいわ。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "You don't have to call me Mistress. I was just messing with you. Call me Gremory."
L41_1.m_Talk_ENG = L42_1
L42_1 = "主人是開玩笑的，你叫我葛茉莉就好。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ไม่ต้องเรียกนายหญิงหรอก ฉันล้อเล่น เรียกเกรมอรีสิ"
L41_1.m_Talk_THA = L42_1
L42_1 = "Cô không cần phải gọi tôi là Cô Chủ. Tôi vừa đùa với cô đấy. Cứ gọi tôi là Gremory cũng được."
L41_1.m_Talk_VTN = L42_1
L42_1 = "让你叫主人只是开玩笑啦。你可以叫我葛茉莉小姐。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Du musst mich nicht Herrin nennen. Ich habe dich nur veräppelt. Nenn mich Gremory."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Je plaisantais, à l'instant. Appelle-moi Gremory."
L41_1.m_Talk_FRA = L42_1
