L43_1 = "나랑 술 한 잔하고 난 뒤엔 언니라고 불러도 좋고."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "飲み友になってくれるならお姉ちゃんでもいいし。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "You can call me sis, too, once we've had a drink together."
L42_1.m_Talk_ENG = L43_1
L43_1 = "和我喝過酒後，也可以叫我茉莉姊。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "จะเรียกพี่สาวก็ได้นะ ถ้าเราได้ดื่มกันแล้วละก้อ"
L42_1.m_Talk_THA = L43_1
L43_1 = "Cô cũng có thể gọi tôi là chị, nếu đồng ý nhậu với tôi một chầu."
L42_1.m_Talk_VTN = L43_1
L43_1 = "如果愿意和我喝一杯，以后叫我姐姐也可以。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Du kannst mich auch Schätzchen nennen, nachdem wir zusammen etwas getrunken haben."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Ou grande sœur, si tu préfères. Mais il faudra sûrement attendre quelques verres avant une telle intimité."
