L48_1 = "GREMORY_BAR_NULL_NULL"
L47_1.m_CharStrID = L48_1
L48_1 = "C"
L47_1.m_Pos = L48_1
L48_1 = "니콜 양은 준비성이 철저한걸? 총을 가지고 다니는 바텐더는 흔치 않거든."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "ニコルちゃんって準備が良いわね。\n銃を持ち歩くバーテンダーなんて滅多にいないから。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Nicole, you came prepared, didn't you? Not many bartenders carry a gun, you know."
L47_1.m_Talk_ENG = L48_1
L48_1 = "妮可，你是一個準備很周全的人嗎？很少看到有調酒師會隨身攜帶槍呢？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "นิโคล เธอทำการบ้านมาดีแล้วใช่มั้ย? คือ บาร์เทนเดอร์เขาไม่ค่อยพกปืนกันหรอกนะ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Nicole, em đã chuẩn bị đầy đủ nhỉ? Chả có mấy nhân viên pha chế mang theo súng đâu."
L47_1.m_Talk_VTN = L48_1
L48_1 = "妮可小姐的准备非常充分呢？携带枪支的调酒师可不多见。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Nicole, du bist vorbereitet gekommen, nicht wahr? Weißt du, nicht viele Barkeeper tragen eine Waffe."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Nicole, c'est ça ? Tu es venue préparée, c'est le moins qu'on puisse dire. Des barmaids armées comme toi, on en croise pas beaucoup."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "GREMORY_ACT1_INTERLUDE1@98#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 98
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3800104
L48_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L48_1.m_bWaitClick = true
