L48_1.m_Face = "UNIT_SURPRISE"
L48_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L49_1 = "C"
L48_1.m_Pos = L49_1
L49_1 = "아, 이건 퇴마… 아니, 호신용으로 가지고 있어요."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "あ、これは退魔……ではなくて、護身用に持っています。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Ah, this is for exor—self-defense purposes."
L48_1.m_Talk_ENG = L49_1
L49_1 = "喔～這是驅魔…不是，是我拿來防身的。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "อ้อ อันนี้สำหรับปรา...เอ่อ.. ป้องกันตัวน่ะค่ะ"
L48_1.m_Talk_THA = L49_1
L49_1 = "À, cái này là để trừ - tự vệ ấy mà."
L48_1.m_Talk_VTN = L49_1
L49_1 = "啊，这是驱魔……不，保护自己用的。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Ach, das ist für den Exor- für Selbstverteidigungszwecke."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Ah, ça ? C'est pour exorci... pour me défendre."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
