L50_1 = "집안에서 내려오는 신성한 가보 같은 건데, 어쩌다 보니 제가 맡게 됐거든요."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "うちの家に代々伝わる神聖な家宝みたいなものなんですが、\nたまたま私が預かることになったんです。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "It's my family's sacred heirloom, and I was put in charge of it somehow."
L49_1.m_Talk_ENG = L50_1
L50_1 = "好像是珍貴的傳家寶吧？不知道為什麼會落到我手上。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "มันเป็นมรดกศักดิ์สิทธิ์ของครอบครัวนะคะ ตอนนี้ฉันก็มีหน้าที่ต้องดูแลค่ะ"
L49_1.m_Talk_THA = L50_1
L50_1 = "Đó là vật gia truyền thiêng liêng của gia đình em, và rồi em đã được giao phụ trách nó."
L49_1.m_Talk_VTN = L50_1
L50_1 = "类似于家里代代相传的传家宝，不知怎么的就到我手里了。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Sie ist ein heiliges Erbstück meiner Familie und wurde mir irgendwie zugeteilt."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Ce fusil est le trésor sacré de ma famille, et c'est moi qui en ai hérité la responsabilité."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
