L3_1 = "GREMORY_ACT1_INTERLUDE1@102#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 102
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 3800104
L2_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L2_1.m_bWaitClick = true
