L3_1 = "UNIT_DESPAIR"
L2_1.m_Face = L3_1
L2_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L3_1 = "C"
L2_1.m_Pos = L3_1
L3_1 = "하하… 아무래도 이런 가게에서 일하려면 두고 오는 편이 좋겠죠?"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "はは……やっぱりこういうお店で働くためには置いてきたほうがいいでしょうか？"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Hah hah... I should leave it home if I work here, right?"
L2_1.m_Talk_ENG = L3_1
L3_1 = "哈哈…帶把槍在店裡上班很怪吧？是不是不帶比較好？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ฮ่าฮ่า... ถ้าทำงานที่นี่ฉันก็ควรทิ้งมันไว้ที่บ้านไม่ใช่หรอคะ?"
L2_1.m_Talk_THA = L3_1
L3_1 = "Ha ha... Em nên để nó ở nhà nếu làm việc ở đây, phải không ạ?"
L2_1.m_Talk_VTN = L3_1
L3_1 = "啊哈哈……如果想要在店里工作，是不是不能随身带着枪？"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Hah hah ... Ich sollte sie lieber zu Hause lassen, wenn ich hier arbeiten will, richtig?"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Ha ha... J-Je le laisserai chez moi quand je viendrai travailler."
L2_1.m_Talk_FRA = L3_1
