L6_1 = "GREMORY_ACT1_INTERLUDE1@105#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 105
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 3800104
L5_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "GREMORY_BAR_NULL_NULL"
L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "L"
L6_1 = "상관없어. 가게에서 소란이나 피우는 불청객은 나도 질색이니까."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "構わないわ。店で騒ぎ立てる迷惑な客はアタシも苦手だから。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "I don't care. I don't want drunken rowdies in my bar, either."
L5_1.m_Talk_ENG = L6_1
L6_1 = "我無所謂，我自己也很討厭那些在店裡鬧事的不速之客。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ฉันไม่สนหรอกนะ แต่ก็ไม่อยากให้มีพวกเมาอาละวาดในร้านด้วย"
L5_1.m_Talk_THA = L6_1
L6_1 = "Không sao. Chị cũng không muốn những tên sâu rượu phá phách trong quán bar của mình."
L5_1.m_Talk_VTN = L6_1
L6_1 = "没关系。因为我也非常讨厌在店里捣乱的不速之客。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Das ist mir egal. Ich will auch keine betrunkenen Rowdys in meiner Bar."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Pas besoin. Un peu de dissuasion ne fait pas de mal, surtout quand il s'agit de corriger les agitateurs."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "GREMORY_ACT1_INTERLUDE1@106#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 106
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 3800104
L6_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L6_1.m_bWaitClick = true
