L7_1 = "UNIT_LAUGH"
L6_1.m_Face = L7_1
L7_1 = "GREMORY_BAR_NULL_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "L"
L7_1 = "실수로 쏴 버려도 뒤처리는 내가 잘해 줄 테니 걱정 마."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "うっかり撃っちゃっても、後始末はアタシがやってあげるから心配しないで。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Even if you shoot them by accident, I can take care of them. Don't worry."
L6_1.m_Talk_ENG = L7_1
L7_1 = "就算你真的不小心擦槍走火，我也會善後的，別擔心～"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ต่อให้เธอบังเอิญไปยิงพวกนั้นเข้าฉันก็จัดการได้ ไม่ต้องห่วง"
L6_1.m_Talk_THA = L7_1
L7_1 = "Dù em có vô tình bắn trúng họ, chị cũng có thể xử lý họ luôn. Đừng lo."
L6_1.m_Talk_VTN = L7_1
L7_1 = "就算失手射中了，我也会替你善后的。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Selbst wenn du jemanden aus Versehen erschießt, kümmere ich mich darum. Keine Sorge."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Et puis ne t'inquiète pas trop. Si tu leur tires dessus par accident, je ferai le ménage derrière. Hi hi."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "GREMORY_ACT1_INTERLUDE1@107#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 107
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 3800104
L7_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_Face = "UNIT_SURPRISE"
L7_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L7_1.m_Pos = "R"
L8_1 = "m_Crash"
L7_1[L8_1] = 20
L8_1 = "네에?! 도시에선 불청객을 그렇게까지 대하나요?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "ええっ！？　都会では迷惑なお客様にそこまでしていいんですか？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Pardon? Is it okay to do that to unwelcome customers in the city?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "蛤？！都市都是這樣對待不速之客的嗎？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ยังไงหรอคะ? ทำอย่างนั้นกับคนในเมืองนี่ก็ไม่เป็นไรเหรอคะ?"
L7_1.m_Talk_THA = L8_1
L8_1 = "Dạ? Làm điều đó với bất cứ người nào trong thành phố này vẫn được ạ?"
L7_1.m_Talk_VTN = L8_1
L8_1 = "什么？这里的人都是这样对待不速之客的吗？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Waaaas? Tut man das in der Stadt mit ungebetenen Gästen?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Pardon ? C'est vraiment légal, de traiter vos clients comme ça ?"
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "GREMORY_ACT1_INTERLUDE1@108#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 108
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 3800104
L8_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L8_1.m_bWaitClick = true
