L9_1 = "GREMORY_BAR_NULL_NULL"
L8_1.m_CharStrID = L9_1
L8_1.m_Pos = "L"
L9_1 = "농담이야."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "なんてね。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "I was just joking."
L8_1.m_Talk_ENG = L9_1
L9_1 = "開玩笑的啦～"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ฉันล้อเล่นหรอก"
L8_1.m_Talk_THA = L9_1
L9_1 = "Đùa thôi."
L8_1.m_Talk_VTN = L9_1
L9_1 = "我开玩笑啦。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Das war nur ein Witz."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Je plaisante, bien sûr."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "GREMORY_ACT1_INTERLUDE1@109#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 109
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 3800104
L9_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L9_1.m_Pos = "R"
L10_1 = "역시 그렇죠? 깜짝 놀랐어요."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "やっぱりそうですよね？　びっくりしました。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "I know, right? You almost had me fooled."
L9_1.m_Talk_ENG = L10_1
L10_1 = "我就知道！嚇我一跳！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ก็ว่าอยู่แหละค่ะ เนอะ? เกือบหลอกฉันได้แล้วนะคะเนี่ย"
L9_1.m_Talk_THA = L10_1
L10_1 = "Em biết mà.Suýt nữa thì em bị lừa rồi."
L9_1.m_Talk_VTN = L10_1
L10_1 = "我就说嘛？吓了我一跳。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Ja, nicht? Du hättest mich fast reingelegt."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Ah, j'aime mieux ça ! Vous m'avez fait peur..."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "GREMORY_ACT1_INTERLUDE1@110#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 110
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 3800104
L10_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "GREMORY_BAR_NULL_NULL"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "L"
L11_1 = "뭐, 뒤처리를 해주겠다는 부분은 진심. 출근할 땐 총도 가져와도 돼."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "まあ、後始末をしてあげるってのは本当よ。出勤する時に銃の持参もオッケー。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Well, I'm serious about taking care of your mess. You can bring your gun to work."
L10_1.m_Talk_ENG = L11_1
L11_1 = "也不完全是開玩笑啦，善後的事我是認真的。你上班的時候可以帶槍，完全沒問題！"
L10_1.m_Talk_TWN = L11_1
L11_1 = "แต่ฉันก็พูดจริงนะเรื่องจะจัดการให้ถ้าเธอยิงเข้าจริงๆ น่ะ เธอพกปืนมาทำงานได้"
L10_1.m_Talk_THA = L11_1
L11_1 = "Chà, chị nghiêm túc về việc chăm sóc bọn họ sau khi em bắn trúng họ đấy. Em có thể mang theo súng đến nơi làm việc."
L10_1.m_Talk_VTN = L11_1
L11_1 = "嗯，可以为你善后那部分是真心的。所以你上班时可以带枪过来。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Tja, aber ich meine es ernst damit, dass ich mich darum kümmere. Du kannst deine Waffe mit zur Arbeit bringen."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Mais je suis sérieuse quand je te dis que je peux faire le ménage derrière toi. Donc tu peux apporter ton fusil au travail."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
