L13_1 = 30
L11_1[L12_1] = L13_1
L12_1 = "그럼 어떤 부분이 농담이었던 거죠?!"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "では、どこが冗談だったんでしょうか！？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Then, which part was a joke?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "那哪句話才句話開玩笑？！"
L11_1.m_Talk_TWN = L12_1
L12_1 = "งั้นตรงไหนคะที่ล้อเล่น?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Vậy thì có phần nào là trò đùa vui cơ chứ?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "那……哪个部分才是玩笑呢？！"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Welcher Teil war dann ein Witz?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Mais euh... Elle était où la plaisanterie, alors ?"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "GREMORY_ACT1_INTERLUDE1@112#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 3800104
L12_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "GREMORY_BAR_NULL_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "L"
L13_1 = "난 오히려 소란 피우는 불청객을 좋아하거든."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "アタシはむしろ、騒ぎ立てる客が好きなのよ。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "That I don't want drunken rowdies. Because I like them."
L12_1.m_Talk_ENG = L13_1
L13_1 = "我反而很喜歡鬧事的不速之客呢～"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ที่ว่าฉันไม่ชอบพวกเมาอาละวาดน่ะ เพราะจริงๆ ฉันชอบ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Chỗ chị không muốn mấy tên sâu rượu say xỉn ấy. Vì rằng là chị lại thích kiểu đấy."
L12_1.m_Talk_VTN = L13_1
L13_1 = "我反而喜欢有来捣乱的不速之客。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Dass ich keine betrunkenen Rowdys will. Im Gegenteil, ich mag sie."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Les agitateurs. Je les aime, tu comprends ?"
L12_1.m_Talk_FRA = L13_1
