L16_1 = "GREMORY_ACT1_INTERLUDE1@115#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 115
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 3800104
L15_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "UNIT_HATE"
L15_1.m_Face = L16_1
L15_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L16_1 = "C"
L15_1.m_Pos = L16_1
L16_1 = "m_bCharPinup"
L15_1[L16_1] = true
L16_1 = "m_bCharPinupEasingTime"
L17_1 = 0.5
L15_1[L16_1] = L17_1
L16_1 = "(뭔가 이상해요. 이 분은 책에서 봤던 <color=#ffd34c>256가지 유형의 직장상사</color> 중에 하나도 맞는 게 없어요.)"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "(何かおかしいです。この方は本で読んだ<color=#ffd34c>256タイプの職場の上司</color>に一つも当てはまりません。)"
L15_1.m_Talk_JPN = L16_1
L16_1 = "(Something's off. She doesn't fit any of the <color=#ffd34c>256 types of bosses</color> I've read about.)"
L15_1.m_Talk_ENG = L16_1
L16_1 = "(好奇怪，她怎麼和我在書上看到的<color=#ffd34c>256種類型的主管</color>都不一樣？)"
L15_1.m_Talk_TWN = L16_1
L16_1 = "(มีอะไรแปลกๆ แฮะ เธอดูไม่ตรงกับแบบใน<color=#ffd34c>หัวหน้าจาก 256 ประเภท</color>ที่ฉันอ่านมาเลย)"
L15_1.m_Talk_THA = L16_1
L16_1 = "(Có điều gì đó không ổn. Cô ấy không phù hợp với bất kỳ <color=#ffd34c>256 kiểu chủ</color> nào mà mình đã đọc.)"
L15_1.m_Talk_VTN = L16_1
L16_1 = "（真是好奇怪。这位老板和我在书中读到的<color=#ffd34c>256种不同类型的职场上司</color>都不符合。）"
L15_1.m_Talk_SCN = L16_1
L16_1 = "(Etwas stimmt nicht. Sie passt zu keinem der <color=#ffd34c>256 Arten von Vorgesetzten</color>, über die ich in Büchern gelesen habe.)"
L15_1.m_Talk_DEU = L16_1
L16_1 = "(C'est louche. Elle ne correspond à aucun des <color=#ffd34c>256 profils d'employeurs</color> que j'ai consultés...)"
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
