L17_1 = {}
L18_1 = "GREMORY_ACT1_INTERLUDE1@117#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 117
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 3800104
L17_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "GREMORY_BAR_NULL_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "L"
L18_1 = "자, 그럼 면접도 끝났겠다. 이제 슬슬 계약서를 써볼까?"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "さて、面接も終わったし、そろそろ契約書を書きましょうか。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Okay, then your interview is over. Now, are you ready to sign your contract?"
L17_1.m_Talk_ENG = L18_1
L18_1 = "那面試就進行到這裡，來簽約吧？"
L17_1.m_Talk_TWN = L18_1
L18_1 = "เอาล่ะ งั้นสัมภาษณ์จบแล้ว พร้อมจะเซ็นสัญญารึยังล่ะ?"
L17_1.m_Talk_THA = L18_1
L18_1 = "Được rồi, phỏng vấn vậy thôi. Bây giờ, em đã sẵn sàng để ký hợp đồng chưa?"
L17_1.m_Talk_VTN = L18_1
L18_1 = "那么，面试结束。现在该签订合同了吧？"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Okay, dann ist dein Vorstellungsgespräch vorbei. Bist du jetzt bereit, deinen Vertrag zu unterschreiben?"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Bon, assez parlé. Tu es prête à signer le contrat ?"
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "GREMORY_ACT1_INTERLUDE1@118#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 118
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 3800104
L18_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_Face = "UNIT_SURPRISE"
L18_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L18_1.m_Pos = "R"
L19_1 = "m_Crash"
L18_1[L19_1] = 20
L19_1 = "벌써요? 고작 잡담 몇 마디 나눈 게 전분데요?"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "えっ、もういいんですか？　まだ雑談しかしていないような気がしますが。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Already? You didn't even ask me any questions."
L18_1.m_Talk_ENG = L19_1
L19_1 = "這麼快？就這樣閒聊幾句就面試完啦？"
L18_1.m_Talk_TWN = L19_1
L19_1 = "เสร็จแล้วเหรอคะ? คุณไม่ได้ถามอะไรฉันสักข้อด้วยซ้ำ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Sẵn sàng chưa á? Chị còn chẳng hỏi gì em mà."
L18_1.m_Talk_VTN = L19_1
L19_1 = "这么快？我们就随便聊了几句而已？"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Jetzt schon? Du hast mir nicht einmal Fragen gestellt."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Déjà ? Mais vous ne m'avez même pas posé une seule question !"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "GREMORY_ACT1_INTERLUDE1@119#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 119
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 3800104
L19_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "GREMORY_BAR_NULL_NULL"
L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "L"
L20_1 = "그걸로 충분해. 사람의 본질은 말 몇 마디에서 드러나는 법이니까."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "それで十分よ。人の本質はちょっとした会話に表れるものだから。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "I don't have to. I can tell who people are just by exchanging a few words with them."
L19_1.m_Talk_ENG = L20_1
L20_1 = "這樣就夠啦，人的本性只要幾句話就可以看出來。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ก็ไม่เห็นต้องถามนี่ คุยกันสองสามคำฉันก็รู้แล้วว่าใครเป็นยังไง"
L19_1.m_Talk_THA = L20_1
L20_1 = "Chị không cần phải làm thế. Chị có thể biết rõ tính cách, khả năng của một người mà chỉ nói vài lời với họ thôi."
L19_1.m_Talk_VTN = L20_1
L20_1 = "这样就足够了~因为有些时候，只要寥寥几句话，就能看出一个人的本质。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Nicht nötig. Man kann Leute schon nach ein paar Worten beurteilen."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Pas besoin. Quelques mots, c'est tout ce dont j'ai besoin pour estimer la valeur de mes interlocuteurs."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "GREMORY_ACT1_INTERLUDE1@120#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 120
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 3800104
L20_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_SURPRISE"
L20_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L20_1.m_Pos = "R"
L21_1 = "저는 바텐더 면접이니 당연히 바텐딩 기술을 시험하실 거라고 생각했어요."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "バーテンダーの面接だから、当然バーテンディングの技術を試されると思っていました。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Since I came here for a bartender job, I thought you'd want to see my bartending skills."
L20_1.m_Talk_ENG = L21_1
L21_1 = "我還以為應徵調酒師，應該會需要考一下調酒技術。　"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ก็ฉันมาทำงานเป็นบาร์เทนเดอร์นี่คะ เลยนึกว่าคุณจะอยากเห็นฝีมือชงเหล้าฉันซะอีก"
L20_1.m_Talk_THA = L21_1
L21_1 = "Vì em đến đây để làm nhân viên pha chế, em tưởng chị muốn xem kỹ năng pha chế nữa."
L20_1.m_Talk_VTN = L21_1
L21_1 = "我还以为调酒师的面试肯定会考验调酒技术呢。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Da das ein Barkeeper-Jobinterview ist, dachte ich, du würdest meine Barkeeper-Fähigkeiten sehen wollen."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Mais je pensais que vous voudriez voir ce que je sais faire derrière le bar, au moins..."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "GREMORY_ACT1_INTERLUDE1@121#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 121
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 3800104
L21_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "GREMORY_BAR_NULL_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "L"
L22_1 = "그런 건 차차 배워 나가면 될 문제야. 바텐더에게 중요한 건 상대방을 대하는 태도와 마음가짐이거든."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "そういうのは徐々に学んでいけばいいの。\nバーテンダーにとって重要なのは、相手に対する態度と心構えなのよ。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "You can learn them as you go. What's more important is how sincere you are to others as a bartender."
L21_1.m_Talk_ENG = L22_1
L22_1 = "技術是可以學的，這不是問題。但調酒師最重要的，是應對客人的心態。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "อันนั้นทำๆ ไปเดี๋ยวก็รู้เอง เรื่องสำคัญกว่าคือเธอเป็นคนจริงใจขนาดไหนต่างหาก"
L21_1.m_Talk_THA = L22_1
L22_1 = "Em có thể học trong quá trình làm việc. Điều quan trọng hơn là em chân thành với người khác như thế nào với tư cách là người pha chế."
L21_1.m_Talk_VTN = L22_1
L22_1 = "那种技术可以以后慢慢学。对调酒师来说，最重要的是对人的态度和自身的心态。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Das kannst du nach und nach lernen. Wichtiger ist, wie aufrichtig du als Barkeeper anderen gegenüber bist."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Faire les cocktails, ça s'apprend avec le temps. Le plus important, c'est d'être sincère avec les clients."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "GREMORY_ACT1_INTERLUDE1@122#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 122
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 3800104
L22_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "GREMORY_BAR_NULL_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "L"
L23_1 = "그리고 그런 마음가짐은 누가 가르친다고 쉽게 변하는 게 아니지."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "そして、そういう心構えは誰かに教わったからって簡単に変わるものじゃない。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "No one can really teach you that."
L22_1.m_Talk_ENG = L23_1
L23_1 = "而心態是無法透過教導就輕易改變的。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "เพราะเรื่องนี้มันสอนกันไม่ได้"
L22_1.m_Talk_THA = L23_1
L23_1 = "Không ai có thể thực sự dạy em điều đó cả."
L22_1.m_Talk_VTN = L23_1
L23_1 = "因为那种心态，就算有人特意传授也很难学会。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Das kann dir niemand wirklich beibringen."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Et ça, ça ne s'apprend pas tout seul."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "GREMORY_ACT1_INTERLUDE1@123#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 123
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 3800104
L23_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "UNIT_LAUGH"
L23_1.m_Face = L24_1
L24_1 = "GREMORY_BAR_NULL_NULL"
L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "L"
L24_1 = "그런 면에서 니콜 양은 합격이야."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "そういう面で、ニコルちゃんは合格よ。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "In that sense, you meet my standards, Nicole."
L23_1.m_Talk_ENG = L24_1
L24_1 = "從這一點來看的話，妮可是合格的。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ซึ่งในทำนองนั้นนี่ คุณสมบัติเธอตรงกับที่ฉันต้องการนะนิโคล"
L23_1.m_Talk_THA = L24_1
L24_1 = "Túm lại là em đáp ứng các tiêu chuẩn của chị, Nicole ạ."
L23_1.m_Talk_VTN = L24_1
L24_1 = "在这方面，妮可小姐是合格的。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Insofern erfüllst du meine Ansprüche, Nicole."
L23_1.m_Talk_DEU = L24_1
L24_1 = "En ce sens, Nicole, tu as réussi l'entretien."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
