L27_1 = "사인은 여기에다 하면 되는 건가요?"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "サインはここにすればいいんですか？"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Okay, should I sign here?"
L26_1.m_Talk_ENG = L27_1
L27_1 = "簽名是簽在這裡嗎？"
L26_1.m_Talk_TWN = L27_1
L27_1 = "เอาล่ะค่ะ ฉันเซ็นตรงนี้ใช่มั้ยคะ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Được rồi, em nên ký tên vào đây ạ?"
L26_1.m_Talk_VTN = L27_1
L27_1 = "在这里签名就可以了吗？"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Okay, soll ich hier unterschreiben?"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Alors je dois juste signer ici ?"
L26_1.m_Talk_FRA = L27_1
