L28_1 = "Yes, there. Over there, too... Good."
L27_1.m_Talk_ENG = L28_1
L28_1 = "對，還有那裡，跟這裡…沒錯。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ใช่ ตรงนั้น แล้วก็ตรงนั้นด้วย... แจ๋ว"
L27_1.m_Talk_THA = L28_1
L28_1 = "Ừ, chỗ đó. Chỗ đó nữa... Tốt."
L27_1.m_Talk_VTN = L28_1
L28_1 = "嗯，是那里。还有这里……很好。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Ja, da. Da drüben auch ... Gut."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Oui. Et là, aussi... Bien."
