L31_1 = "GREMORY_ACT1_INTERLUDE1@130#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 130
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 3800104
L30_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
