L30_1.m_fWaitTime = 0
L31_1 = "UNIT_LAUGH"
L30_1.m_Face = L31_1
L31_1 = "GREMORY_BAR_NULL_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "C"
L30_1.m_Pos = L31_1
L31_1 = "아니, 아무것도 아니야."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "ううん、何でもないわ。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Ah, nothing."
L30_1.m_Talk_ENG = L31_1
L31_1 = "沒事，沒什麼。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "อ้อ ไม่มีอะไรหรอก"
L30_1.m_Talk_THA = L31_1
L31_1 = "À, không có gì."
