L32_1 = "GREMORY_ACT1_INTERLUDE1@131#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 131
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3800104
L31_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "UNIT_IDLE"
L31_1.m_Face = L32_1
L32_1 = "GREMORY_BAR_NULL_NULL"
L31_1.m_CharStrID = L32_1
L32_1 = "C"
L31_1.m_Pos = L32_1
L32_1 = "미안하지만 계약서는 나중에 쓰자. 정직원이 되기 전에, 니콜 양이 이 일에 적성에 맞는지 먼저 확인해보는 거야."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "悪いけど、契約書は後にしましょう。正式に働く前に、\nニコルちゃんが本当にこの仕事に適性があるか、まずは試してみないと。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "I'm sorry, but let's sign your contract later. Before I hire you as a regular employee, I want to make sure you really like being a bartender."
L31_1.m_Talk_ENG = L32_1
L32_1 = "不好意思，合約等之後再完成吧。在你正式成為員工之前，我想先確認一下你是否適合這份工作。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "โทษทีนะ แต่ค่อยเซ็นสัญญากันทีหลังดีกว่า ก่อนจะจ้างเธอเป็นพนักงานประจำนี่ ฉันอยากแน่ใจว่าเธออยากเป็นบาร์เทนเดอร์จริงๆ ก่อน"
L31_1.m_Talk_THA = L32_1
L32_1 = "Chị xin lỗi nhưng hãy ký hợp đồng sau nhé. Trước khi tuyển dụng em làm một nhân viên chính thức, chị muốn chắc là em thực sự thích trở thành nhân viên pha chế."
L31_1.m_Talk_VTN = L32_1
L32_1 = "抱歉，合同的事情还是暂缓一下吧。我想在妮可小姐成为正式职员前，看看你是否真的适合这个工作。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Tut mir leid, aber lass uns deinen Vertrag später unterschreiben. Bevor ich dich als feste Mitarbeiterin einstelle, möchte ich sichergehen, dass dir die Arbeit wirklich liegt."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Désolée, mais nous signerons ton contrat plus tard. Je voudrais d'abord m'assurer que tu vraiment le profil que nous recherchons."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "GREMORY_ACT1_INTERLUDE1@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3800104
L32_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "UNIT_LAUGH"
L32_1.m_Face = L33_1
L32_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L33_1 = "C"
L32_1.m_Pos = L33_1
L33_1 = "열심히 할게요! 일은 당장이라도 시작할 수 있어요!"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "一生懸命頑張ります！　仕事は今すぐにでも始められます！"
L32_1.m_Talk_JPN = L33_1
L33_1 = "I'll work hard! I can start right now if you want!"
L32_1.m_Talk_ENG = L33_1
L33_1 = "我會努力的！我可以立刻上工！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ฉันจะพยายามเต็มที่เลยค่ะ! เริ่มงานตอนนี้เลยก็ได้นะคะถ้าคุณต้องการ!"
L32_1.m_Talk_THA = L33_1
L33_1 = "Em sẽ làm việc chăm chỉ! Em có thể bắt đầu ngay bây giờ nếu chị muốn!"
L32_1.m_Talk_VTN = L33_1
L33_1 = "我会认真努力的！工作的话，可以现在就开始！"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Ich werde mein Bestes geben! Ich kann sofort anfangen, wenn du willst!"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Tout ce que voulez ! Je peux même commencer tout de suite !"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "GREMORY_ACT1_INTERLUDE1@133#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 133
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3800104
L33_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
