L34_1 = "UNIT_LAUGH"
L33_1.m_Face = L34_1
L34_1 = "GREMORY_BAR_NULL_NULL"
L33_1.m_CharStrID = L34_1
L34_1 = "C"
L33_1.m_Pos = L34_1
L34_1 = "후훗. 의욕이 넘쳐서 좋네."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "フフッ、やる気満々でいいわね。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Hah hah. You're so enthusiastic, aren't you?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "呵呵，非常好，這麼有拚勁！"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ฮ่าฮ่า กระตือรือร้นมากเลยนะเราเนี่ย"
L33_1.m_Talk_THA = L34_1
L34_1 = "Ha ha. Em hăng hái quá nhỉ?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "呼呼。真是充满干劲呢。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Haha. Schön, dass du so begeistert bist."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Hé hé, quel enthousiasme !"
L33_1.m_Talk_FRA = L34_1
