L36_1 = "m_bCharPinup"
L35_1[L36_1] = true
L36_1 = "m_bCharPinupEasingTime"
L37_1 = 0.5
L35_1[L36_1] = L37_1
L36_1 = "(괜한 걱정을 했네요. 가게 주인 분이 그렇게 까다로운 사람은 아니라 다행이에요.)"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "(余計な心配でした。店主の方がそんなに気難しい方ではなさそうでよかったです。)"
L35_1.m_Talk_JPN = L36_1
L36_1 = "(I worried for nothing. I'm glad my boss isn't a difficult person.)"
L35_1.m_Talk_ENG = L36_1
L36_1 = "(根本是白擔心的嘛 ～幸好這家店的老闆娘不是難搞的人！)"
L35_1.m_Talk_TWN = L36_1
L36_1 = "(ฉันกังวลไปซะเปล่าๆ ดีใจจังที่บอสคุยด้วยง่าย)"
L35_1.m_Talk_THA = L36_1
L36_1 = "(Mình chẳng có gì phải lo lắng. Mình vui vì chủ quán không phải người khó tính.)"
L35_1.m_Talk_VTN = L36_1
L36_1 = "（白担心了。还好酒吧的老板不是那么刻薄的人。）"
L35_1.m_Talk_SCN = L36_1
L36_1 = "(Ich habe mir umsonst Sorgen gemacht. Ich bin froh, dass meine Chefin keine schwierige Person ist.)"
L35_1.m_Talk_DEU = L36_1
L36_1 = "(Ouf, je m'inquiétais pour rien. La patronne est super abordable, en fait !)"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "GREMORY_ACT1_INTERLUDE1@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
