L37_1 = "m_bCharPinup"
L36_1[L37_1] = true
L37_1 = "(위장은 성공적인 것 같으니, 이제 악마를 찾기만 하면 되겠어요!)"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "(潜入には成功したみたいですし、あとは悪魔を探すだけ！)"
L36_1.m_Talk_JPN = L37_1
L37_1 = "(Now that I've successfully infiltrated the place, I just need to find the devil!)"
L36_1.m_Talk_ENG = L37_1
L37_1 = "(看來我的偽裝很成功，接下來就專心揪出魔鬼吧！)"
L36_1.m_Talk_TWN = L37_1
L37_1 = "(ในเมื่อฉันแทรกซีมเข้ามาที่นี่ได้แล้ว ทีนี้ก็แค่ต้องหาเจ้าปีศาจนั่นให้เจอเท่านั้น)"
L36_1.m_Talk_THA = L37_1
L37_1 = "(Bây giờ mình đã thành công trà trộn vào nơi này, mình chỉ cần tìm ra con ác ma nữa thôi!)"
L36_1.m_Talk_VTN = L37_1
L37_1 = "（看来伪装很成功，现在只要找出恶魔就可以了！）"
L36_1.m_Talk_SCN = L37_1
L37_1 = "(Jetzt, wo ich den Ort erfolgreich infiltriert habe, muss ich nur noch den Teufel finden!)"
L36_1.m_Talk_DEU = L37_1
L37_1 = "(Bien, infiltration réussie ! Et maintenant, je dois juste retrouver ce petit diable...)"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
