L39_1 = "GREMORY_BAR_NULL_NULL"
L38_1.m_CharStrID = L39_1
L39_1 = "C"
L38_1.m_Pos = L39_1
L39_1 = "하지만 일을 시작하기 전에 먼저 우리 가게에서 일하는 법을 배워야겠지?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "でも仕事を始める前に、まずはうちの店のやり方を覚えてもらわないとね？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "But before you start, you need to learn a few things about this bar."
L38_1.m_Talk_ENG = L39_1
L39_1 = "不過在開始上班前，要先知道一下我們店裡的規矩吧？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "แต่ก่อนจะเริ่มเนี่ย มีบางเรื่องที่เธอต้องรู้เกี่ยวกับบาร์นี้ก่อน"
L38_1.m_Talk_THA = L39_1
L39_1 = "Nhưng trước khi bắt đầu, em cần học hỏi vài điều về quán bar này."
L38_1.m_Talk_VTN = L39_1
L39_1 = "但在开始工作前，你需要先学习下在我们店里工作的方式。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Aber bevor du anfängst, musst du ein paar Dinge über diese Bar lernen."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Avant de commencer, il y a deux trois choses que tu dois connaître à propos de cet endroit."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
