L40_1 = "C"
L39_1.m_Pos = L40_1
L40_1 = "우리 꼬마 임금님이 가르쳐 줄 테니 잘 배워 보도록 해."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "うちの小さな王様が教えてくれるから、よく聞いて覚えるようにね。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Little majesty here will teach them to you."
L39_1.m_Talk_ENG = L40_1
L40_1 = "小不點國王會教你，你要好好學。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ฝ่าบาทผู้นี้จะเป็นคนสอนเธอเอง"
L39_1.m_Talk_THA = L40_1
L40_1 = "Tiểu Điện Hạ sẽ dạy em."
L39_1.m_Talk_VTN = L40_1
L40_1 = "我们的小女王陛下会教你的。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Die kleine Majestät hier wird sie dir beibringen."
L39_1.m_Talk_DEU = L40_1
L40_1 = "La jeune impératrice ici présente va te faire un briefing."
L39_1.m_Talk_FRA = L40_1
