L44_1 = "자, 잘 왔다, 신입. 지금부터 교육을 시작하도록 하마."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "よ、よくぞ来た、新人。これより教育を始めるとしよう。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "W-welcome, recruit. Let's start your training."
L43_1.m_Talk_ENG = L44_1
L44_1 = "歡…迎你，菜鳥。現在開始員工教育訓練。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ยะ-ยินดีต้อนรับ เจ้าคนใหม่ มาเริ่มการฝึกฝนของเจ้ากันเถอะ"
L43_1.m_Talk_THA = L44_1
L44_1 = "C-Chào mừng, người mới. Bắt đầu học tập nào!"
L43_1.m_Talk_VTN = L44_1
L44_1 = "来、来得正好，新人。现在就开始新人教学。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "W-willkommen, Rekrutin. Lass uns dein Training beginnen."
L43_1.m_Talk_DEU = L44_1
L44_1 = "S-Salut, la nouvelle ! C'est moi qui vais me charger de ta formation."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "GREMORY_ACT1_INTERLUDE1@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
