L48_1 = 0.5
L46_1[L47_1] = L48_1
L47_1 = "(좀 전에 봤던 악마가 여기 있는데요? 역시 꿈이 아니었어요.)"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "(さっき見た悪魔がここにいます。やっぱり夢ではありませんでした！)"
L46_1.m_Talk_JPN = L47_1
L47_1 = "(Here's the devil I saw earlier. It wasn't a dream at all.)"
L46_1.m_Talk_ENG = L47_1
L47_1 = "(剛才看到的魔鬼原來在這裡？我果然不是在作夢！)"
L46_1.m_Talk_TWN = L47_1
L47_1 = "(นี่มันปีศาจที่เจอก่อนหน้านี้นี่ ฉันไม่ได้ฝันไปนี่นา)"
L46_1.m_Talk_THA = L47_1
L47_1 = "(Đây là con ác ma mà mình đã thấy trước đó. Chứng tỏ đó không phải là giấc mơ.)"
L46_1.m_Talk_VTN = L47_1
L47_1 = "（嗯？她是之前看到的恶魔？果然不是做梦？）"
L46_1.m_Talk_SCN = L47_1
L47_1 = "(Hier ist der Teufel, den ich vorhin gesehen habe. Es war also kein Traum.)"
L46_1.m_Talk_DEU = L47_1
L47_1 = "(Le diable de tout à l'heure ! Alors ce n'était pas un rêve...)"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "GREMORY_ACT1_INTERLUDE1@147#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 147
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 3800104
L47_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "UNIT_SERIOUS"
L47_1.m_Face = L48_1
L47_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L47_1.m_Pos = "L"
L48_1 = "m_bCharPinup"
L47_1[L48_1] = true
L48_1 = "(아니, 하지만 그렇다고 하기엔 절 못 알아보는 것 같은데요?)"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "(いえ、でもそのはずなのに私のことを覚えていないようですね？)"
L47_1.m_Talk_JPN = L48_1
L48_1 = "(But wait, I don't think she remembers me.)"
L47_1.m_Talk_ENG = L48_1
L48_1 = "(等等，但她似乎不認得我？)"
L47_1.m_Talk_TWN = L48_1
L48_1 = "(แต่เดี๋ยวนะ เธอดูจะจำฉันไม่ได้แฮะ)"
L47_1.m_Talk_THA = L48_1
L48_1 = "(Nhưng chờ đã, mình không nghĩ là cô ta còn nhớ mình.)"
L47_1.m_Talk_VTN = L48_1
L48_1 = "（不，好像她完全认不出我？）"
L47_1.m_Talk_SCN = L48_1
L48_1 = "(Aber Moment, ich glaube nicht, dass sie sich an mich erinnert.)"
L47_1.m_Talk_DEU = L48_1
L48_1 = "(Mais... On dirait qu'elle ne se souvient pas de moi ?)"
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "GREMORY_ACT1_INTERLUDE1@148#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 148
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3800104
L48_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L48_1.m_bWaitClick = true
