L48_1.m_Pos = "L"
L49_1 = "m_bCharPinup"
L48_1[L49_1] = true
L49_1 = "(이번엔 신중해지는 편이 좋겠어요. 어쩌면 진짜 뿔이 아닐 수도 있고…)"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "(今度は慎重になったほうがよさそうです。\nもしかしたら本物の角ではない可能性もありますし……)"
L48_1.m_Talk_JPN = L49_1
L49_1 = "(I'd better be careful this time. It's possible they're not real horns...)"
L48_1.m_Talk_ENG = L49_1
L49_1 = "(這次還是別太衝動，說不定那不是真的角…)"
L48_1.m_Talk_TWN = L49_1
L49_1 = "(คราวนี้ฉันระวังไว้ก่อนดีกว่า นั่นอาจไม่ใช่เขาจริงก็ได้...)"
L48_1.m_Talk_THA = L49_1
L49_1 = "(Lần này mình nên cẩn thận. Có thể chúng không phải là sừng thật...)"
L48_1.m_Talk_VTN = L49_1
L49_1 = "（这次得慎重一些。或许那个角不是真的……）"
L48_1.m_Talk_SCN = L49_1
L49_1 = "(Ich sollte diesmal noch besser aufpassen. Es könnte sein, dass das keine echten Hörner sind ...)"
L48_1.m_Talk_DEU = L49_1
L49_1 = "(Prudence, Nicole. Ses cornes ne sont peut-être pas des vraies.)"
L48_1.m_Talk_FRA = L49_1
