L3_1 = 50
L1_1[L2_1] = L3_1
L2_1 = "으아아앗, 잠깐! 부러져! 그렇게 당기면 부러진다고!"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "ふえええ、ちょっと待って！　折れちゃう！　そんなに引っ張ったら折れちゃうよお！"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Ow, ow! Hey, stop pulling on my horns! You're going to break them!"
L1_1.m_Talk_ENG = L2_1
L2_1 = "哎唷，放手啦！你幹嘛！這樣拉會斷掉啦！"
L1_1.m_Talk_TWN = L2_1
L2_1 = "โอ๊ย โอ๊ย! นี่ หยุดดึงเขาข้าเดี๋ยวนี้นะ! เจ้าจะทำมันหักอยู่แล้ว!"
L1_1.m_Talk_THA = L2_1
L2_1 = "Ối, ôi! Này, đừng kéo sừng của ta nữa! Cô sẽ làm hỏng chúng mất!"
L1_1.m_Talk_VTN = L2_1
L2_1 = "呃啊啊啊，等下！要断了！这么掰会断掉的啦！"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Au, aua! Hey, hör auf, an meinen Hörnern zu ziehen! Sonst brechen sie noch!"
L1_1.m_Talk_DEU = L2_1
L2_1 = "Aïe, ça fait mal ! Non mais t'es pas bien ? Tire pas sur mes cornes comme ça, tu va les casser !"
L1_1.m_Talk_FRA = L2_1
