L4_1 = "GREMORY_ACT1_INTERLUDE1@153#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 153
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 3800104
L3_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Face = "UNIT_SURPRISE"
L3_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L4_1 = "C"
L3_1.m_Pos = L4_1
L4_1 = "m_Crash"
L3_1[L4_1] = 20
L4_1 = "앗?! 죄송해요! 좀처럼 보기 어려운 거라 무심코 그만…!"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "あっ！？　すみません！　とても珍しくてつい……！"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Ah? I'm sorry! I just... I've never seen anything like them..."
L3_1.m_Talk_ENG = L4_1
L4_1 = "喔？！抱歉！覺得有點稀奇，不知不覺就…！"
L3_1.m_Talk_TWN = L4_1
L4_1 = "อ๊ะ? ขอโทษค่ะ! ฉันแค่... ไม่เคยเห็นอะไรแบบนี้..."
L3_1.m_Talk_THA = L4_1
L4_1 = "Ah? Tôi xin lỗi! Tôi chỉ... tôi chưa bao giờ thấy bất cứ thứ gì giống thế..."
L3_1.m_Talk_VTN = L4_1
L4_1 = "啊？！对不起！因为从来没见过所以不自觉就……！"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Huch? Das tut mir leid! Ich habe nur ... ich habe noch nie so etwas gesehen ..."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Oh ? Ah, désolée ! C'est juste que... Je n'avais jamais rien vu de tel !"
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "GREMORY_ACT1_INTERLUDE1@154#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 154
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 3800104
L4_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L4_1.m_bWaitClick = true
