L4_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L5_1 = "C"
L4_1.m_Pos = L5_1
L5_1 = "그런데 그 뿔, 머리띠 장식이 아니네요."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "この角、カチューシャとかではないんですね。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "But your horns, they're not decorations."
L4_1.m_Talk_ENG = L5_1
L5_1 = "不過我還以為那個角是頭飾，原來不是喔？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "แต่เขาคุณ มันไม่ใช่เครื่องประดับนี่คะ"
L4_1.m_Talk_THA = L5_1
L5_1 = "Nhưng sừng của cô, chúng không phải là đồ trang trí."
L4_1.m_Talk_VTN = L5_1
L5_1 = "但是那个角，不是发卡装饰吗？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Aber deine Hörner sind gar keine Dekoration."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Ce sont des vraies cornes ? Pas des accessoires de mode ?"
L4_1.m_Talk_FRA = L5_1
