L6_1 = "그야 당연하지! 이 뿔은 마왕의 상징이다!"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "それは当然だ！　この角は魔王の象徴！"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Of course not! They're the symbol of the Demon Lord!"
L5_1.m_Talk_ENG = L6_1
L6_1 = "當然不是！這可是魔王的標誌！"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ก็ไม่ใช่นะสิ! มันเป็นสัญลักษณ์ของเจ้าแห่งดีม่อน"
L5_1.m_Talk_THA = L6_1
L6_1 = "Dĩ nhiên là không! Chúng là biểu tượng của Chúa Quỷ!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "当然不是！这可是魔王的象征！"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Natürlich nicht! Sie sind das Symbol eines Dämonenfürsten!"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Évidemment ! Ces cornes sont le symbole des seigneurs démons, leur signe distinctif !"
L5_1.m_Talk_FRA = L6_1
