L7_1.m_fTalkTime = 0.03
L8_1 = "それってなんですか？　悪魔とは違うものですか？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "What's that? Is it different from normal devils?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "那是什麼？和魔鬼不一樣嗎？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "มันคืออะไรเหรอ? มันต่างจากปีศาจธรรมดายังไงอะ?"
L7_1.m_Talk_THA = L8_1
L8_1 = "Đó là cái thứ gì? Nó khác gì so với lũ ác ma bình thường?"
L7_1.m_Talk_VTN = L8_1
L8_1 = "那是什么？和恶魔有什么不同？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Was ist das? Unterscheidet es sich von Teufeln?"
