L10_1 = 30
L8_1[L9_1] = L10_1
L9_1 = "무엄하구나! 감히 마왕을 악마와 같은 취급 하다니!"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "無礼者め！　魔王と悪魔を同じ扱いにするとは！"
L8_1.m_Talk_JPN = L9_1
L9_1 = "How dare you? We Demon Lords are totally different from lowly devils!"
L8_1.m_Talk_ENG = L9_1
L9_1 = "大膽！竟然將魔王和魔鬼相提並論！"
L8_1.m_Talk_TWN = L9_1
L9_1 = "กล้าดียังไง? เจ้าแห่งดีม่อนอย่างเราต้องต่างกับพวกปีศาจชั้นต่ำแบบคนละเรื่องอยู่แล้วสิ!"
L8_1.m_Talk_THA = L9_1
L9_1 = "Sao cô dám? Chúa Quỷ bọn ta, hoàn toàn khác với những con ác ma hạ đẳng!"
L8_1.m_Talk_VTN = L9_1
L9_1 = "真是放肆！竟敢将本魔王与区区恶魔相提并论！"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Wie kannst du es wagen! Wir Dämonenfürsten sind völlig anders als niedere Teufel!"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Comment oses-tu ! Nous, les seigneurs démons, nous n'avons rien à voir avec ces misérables créatures !"
L8_1.m_Talk_FRA = L9_1
