L17_1 = "멋대로 줄여서 부르지 마!"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "勝手に略して呼ぶな！"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Don't shorten my name like that!"
L16_1.m_Talk_ENG = L17_1
L17_1 = "不要隨便把人家的名字縮寫好嗎！"
L16_1.m_Talk_TWN = L17_1
L17_1 = "อย่ามาย่อชื่อข้าแบบนั้นนะ!"
L16_1.m_Talk_THA = L17_1
L17_1 = "Đừng có rút ngắn tên ta!"
L16_1.m_Talk_VTN = L17_1
L17_1 = "别随便用简称！"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Verkürze meinen Namen nicht so!"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Ne m'appelle pas par ce surnom débile !"
