L18_1 = "MOMO_BAR_NULL_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "L"
L18_1 = "이 몸의 이름은 울던 아기도 뚝 그치게 만드는 무시무시한 이름이니라!"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "吾輩の尊名は泣く子も黙る恐ろしい名前である！"
L17_1.m_Talk_JPN = L18_1
L18_1 = "My name alone can make babies stop crying, because I'm so terrifying!"
L17_1.m_Talk_ENG = L18_1
L18_1 = "本王的名字可是可怕到，能讓哭泣中的嬰兒立刻閉嘴呢！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ลำพังได้ยินชื่อข้าแม้แต่ทารกยังหยุดร้องไห้ เพราะข้าน่ะน่ากลัวเป็นที่สุด!"
L17_1.m_Talk_THA = L18_1
L18_1 = "Chỉ riêng cái tên của ta thôi cũng có thể khiến bọn trẻ con không ngừng khóc, bởi vì ta quá khủng bố!"
L17_1.m_Talk_VTN = L18_1
L18_1 = "本尊的赫赫凶名，可是让小儿闻之止啼的！"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Allein mein Name kann Babys zum Weinen bringen, weil ich so furchteinflößend bin!"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Je suis si terrifiante que mon nom seul suffit à sécher les larmes des nouveaux-nés, figure-toi !"
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
