L19_1 = "UNIT_LAUGH"
L18_1.m_Face = L19_1
L18_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L18_1.m_Pos = "R"
L19_1 = "베이비시터라니. 어린 나이에 기특하네요."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "ベビーシッターの仕事もしているんですか？　まだ幼いのに偉いですね。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Oh, you babysit? That's not an easy job for a young girl like you."
L18_1.m_Talk_ENG = L19_1
L19_1 = "原來你是保母？年紀輕輕就當保母，很少見呢！"
L18_1.m_Talk_TWN = L19_1
L19_1 = "โอ๊ะ คุณเลี้ยงเด็กด้วยเหรอคะ? คุณเองก็ยังเด็ก นั่นไม่ง่ายเลยนะคะ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Ồ, cô làm nghề trông trẻ sao? Đó không phải là một công việc dễ dàng đối với một cô bé như cô."
L18_1.m_Talk_VTN = L19_1
L19_1 = "唉？止啼？所以你是保姆吗？这么小的年纪，真是没想到。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Oh, du babysittest? Das ist keine leichte Aufgabe für ein junges Mädchen wie dich."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Oh, tu fais du babysitting ? Ça ne doit pas être facile pour une jeune fille comme toi."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
