L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "L"
L21_1 = "그리고 어리지 않아! 난 나이가 아주 많다고!"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "そして幼くなぞない！　吾輩はかなり年を取っているのだ！"
L20_1.m_Talk_JPN = L21_1
L21_1 = "And also, I'm not young! I'm very old, you know!"
L20_1.m_Talk_ENG = L21_1
L21_1 = "而且我一點也不小！我年紀超大的！"
L20_1.m_Talk_TWN = L21_1
L21_1 = "แล้วข้าก็ไม่เด็กด้วย! ข้าแก่มากแล้วรู้ไว้ซะ!"
L20_1.m_Talk_THA = L21_1
L21_1 = "Và nữa, ta không trẻ đâu! Ta rất già rồi!"
L20_1.m_Talk_VTN = L21_1
L21_1 = "而且年纪也不小！我年纪可大了！"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Und außerdem bin ich nicht jung! Ich bin sehr alt, damit das klar ist!"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Et je suis pas jeune du tout !"
L20_1.m_Talk_FRA = L21_1
