L27_1 = "GREMORY_ACT1_INTERLUDE1@176#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 176
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 3800104
L26_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L26_1.m_bWaitClick = true
