L27_1 = "UNIT_SERIOUS"
L26_1.m_Face = L27_1
L26_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L26_1.m_Pos = "R"
L27_1 = "m_bCharPinup"
L26_1[L27_1] = true
L27_1 = "m_bCharPinupEasingTime"
L28_1 = 0.3
L26_1[L27_1] = L28_1
L27_1 = "(속을 뻔했어요. 자그마치 3만 살이라니… 평범한 인간은 아니네요.)"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "(あやうく騙されるところでした。なんと3万歳だなんて……\n普通の人間ではありませんね。)"
L26_1.m_Talk_JPN = L27_1
L27_1 = "(She almost had me fooled. Thirty thousand years old? I knew she wasn't an ordinary human!)"
L26_1.m_Talk_ENG = L27_1
L27_1 = "(差點被她的外表給欺騙，竟然已經三萬歲…果然不是普通人！)"
L26_1.m_Talk_TWN = L27_1
L27_1 = "(เกือบโดนหลอกแล้วมั้ยล่ะ สามหมื่นปีงั้นเหรอ? กะแล้วว่าเธอไม่ใช่มนุษย์ธรรมดา!)"
L26_1.m_Talk_THA = L27_1
L27_1 = "Suýt nữa thì mình bị lừa. Ba mươi nghìn tuổi? Mình biết cô ả này không phải là người bình thường mà!)"
L26_1.m_Talk_VTN = L27_1
L27_1 = "（差点被骗到。竟然有3万岁……果然不是普通人类。）"
L26_1.m_Talk_SCN = L27_1
L27_1 = "(Fast wäre ich getäuscht worden. 30.000 Jahre alt ist sie? Ich wusste doch, dass sie kein gewöhnlicher Mensch ist!)"
L26_1.m_Talk_DEU = L27_1
L27_1 = "(Elle a failli m'avoir. Trente mille ans ? Ce n'est pas une humaine ordinaire, j'en étais sûre !)"
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "GREMORY_ACT1_INTERLUDE1@177#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 177
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 3800104
L27_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L27_1.m_Pos = "R"
L28_1 = "m_bCharPinup"
L27_1[L28_1] = true
L28_1 = "(귀여운 어린아이 모습으로 절 방심시키다니 간사하군요. 악마답다고 해야 할까요.)"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "(かわいい子供の姿で私を油断させるなんてずる賢いですね。悪魔らしいというべきでしょうか。)"
L27_1.m_Talk_JPN = L28_1
L28_1 = "(Such a cunning devil, using its innocent childlike appearance to make me lower my guard.)"
L27_1.m_Talk_ENG = L28_1
L28_1 = "(是想用可愛的外表讓我卸下心防嗎？真是奸詐！這是魔鬼會用的招數嗎？)"
L27_1.m_Talk_TWN = L28_1
L28_1 = "(เจ้าเล่ห์นักนะคะคุณปีศาจ เอารูปลักษณ์แบบเด็กน้อยไร้เดียงสามาหลอกให้ฉันประมาทเนี่ย)"
L27_1.m_Talk_THA = L28_1
L28_1 = "(Thật là một con ác ma xảo trá, lợi dụng vẻ ngoài ngây ngô như trẻ con để làm mình mất cảnh giác.)"
L27_1.m_Talk_VTN = L28_1
L28_1 = "（用可爱孩子的模样让我疏忽大意，真是狡猾。果然是恶魔。）"
L27_1.m_Talk_SCN = L28_1
L28_1 = "(Das ist echt teuflisch von ihr, mich mit einem unschuldigen, kindlichen Aussehen zu übertölpeln.)"
L27_1.m_Talk_DEU = L28_1
L28_1 = "(Prendre l'apparence d'une petite fille pour me faire baisser ma garde... Ce diable est terriblement rusé !)"
L27_1.m_Talk_FRA = L28_1
