L30_1 = "GREMORY_ACT1_INTERLUDE1@179#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 179
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 3800104
L29_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_SURPRISE"
L30_1 = "MOMO_BAR_NULL_NULL"
L29_1.m_CharStrID = L30_1
L30_1 = "C"
L29_1.m_Pos = L30_1
L30_1 = "m_Crash"
L29_1[L30_1] = 20
L30_1 = "뭐, 뭐냐. 그렇게 노려보다니."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "な、なんだ。なにをそんなにジロジロ見ている。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "W-what? Why are you glaring at me like that?"
L29_1.m_Talk_ENG = L30_1
L30_1 = "你…你幹嘛，幹嘛一直盯著我看？"
L29_1.m_Talk_TWN = L30_1
L30_1 = "อะ-อะไร? ทำไมจ้องฉันแบบนั้นล่ะ?"
L29_1.m_Talk_THA = L30_1
L30_1 = "C-cái gì? Tại sao lại nhìn ta như thế?"
L29_1.m_Talk_VTN = L30_1
L30_1 = "怎、怎么了。为什么瞪着我。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "W-was ist? Warum starrst du mich so an?"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Q-Quoi ? Pourquoi tu me regardes comme ça ?"
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
