L32_1 = "GREMORY_ACT1_INTERLUDE1@181#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 181
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3800104
L31_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_SURPRISE"
L31_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L32_1 = "C"
L31_1.m_Pos = L32_1
L32_1 = "m_Crash"
L31_1[L32_1] = 20
L32_1 = "앗, 죄송해요. 잠시 다른 생각을 하느라."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "あっ、すみません。ちょっと他のことを考えちゃって。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Oh, sorry. I was distracted for a moment."
L31_1.m_Talk_ENG = L32_1
L32_1 = "喔，不好意思，我剛在想其他事。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "โอ๊ะ ขอโทษค่ะ พอดีฉันเผลอคิดอะไรไป"
L31_1.m_Talk_THA = L32_1
L32_1 = "Ồ, xin lỗi nhé. Tôi đã bị phân tâm trong giây lát."
L31_1.m_Talk_VTN = L32_1
L32_1 = "啊，抱歉。只是暂时走神而已。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Oh, Entschuldigung. Ich war für einen Moment abgelenkt."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Oh pardon. J'ai eu un moment d'égarement."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "GREMORY_ACT1_INTERLUDE1@182#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 182
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3800104
L32_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "UNIT_IDLE"
L32_1.m_Face = L33_1
L32_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L33_1 = "C"
L32_1.m_Pos = L33_1
L33_1 = "그러면 뭐부터 시작하면 좋을까요? 화장실 청소?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "それでは何から始めればいいでしょう？　トイレ掃除？"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Okay, what do you want me to do? Clean the restrooms?"
L32_1.m_Talk_ENG = L33_1
L33_1 = "那要怎麼開始呢？先打掃廁所嗎？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เอาล่ะค่ะ อยากให้ฉันทำอะไรเหรอคะ? ล้างห้องน้ำเหรอ?"
L32_1.m_Talk_THA = L33_1
L33_1 = "Được rồi, cô muốn tôi làm gì? Dọn phòng vệ sinh à?"
L32_1.m_Talk_VTN = L33_1
L33_1 = "那么要从哪开始呢？打扫卫生间？"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Okay, was soll ich tun? Toiletten reinigen?"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Bien, je commence par quoi ? Nettoyer les toilettes ?"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
