L38_1 = 30
L36_1[L37_1] = L38_1
L37_1 = "흐엑…! 해, 해치지 마세요!"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "ひいっ……！　い、いじめないでください！"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Heek! P-please don't hurt me!"
L36_1.m_Talk_ENG = L37_1
L37_1 = "嗚…！別…別殺我！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ว้ายยย! ยะ-อย่าทำหนูนะ!"
L36_1.m_Talk_THA = L37_1
L37_1 = "Ơ! Đ-đừng làm ta bị thương!"
L36_1.m_Talk_VTN = L37_1
L37_1 = "呃……！请、请不要伤害我！"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Hieek! B-bitte tu mir nichts an!"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Gloups...! S-S'il te plaît, ne me fais pas de mal !"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "GREMORY_ACT1_INTERLUDE1@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3800104
L37_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "UNIT_IDLE"
L37_1.m_Face = L38_1
L37_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L37_1.m_Pos = "R"
L38_1 = "네?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "はい？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Excuse me?"
L37_1.m_Talk_ENG = L38_1
L38_1 = "蛤？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ว่าไงนะคะ?"
L37_1.m_Talk_THA = L38_1
L38_1 = "Gì cơ?"
L37_1.m_Talk_VTN = L38_1
L38_1 = "嗯？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Wie bitte?"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Pardon ?"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "GREMORY_ACT1_INTERLUDE1@188#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 188
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3800104
L38_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "MOMO_BAR_NULL_NULL"
L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "L"
L39_1 = "아, 아니… 음료 만드는 법부터 해치울 거라고 말했을 뿐이다."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "あ、いや……ソフトドリンク作りからやると言おうとしただけだ。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "A-hem... I said you should make some drinks first."
L38_1.m_Talk_ENG = L39_1
L39_1 = "喔，沒事…我說別在那邊殺時間，先學怎麼調製飲料吧！"
L38_1.m_Talk_TWN = L39_1
L39_1 = "อะ-แฮ่ม... ข้าบอกว่าเจ้าควรทำเครื่องดื่มก่อนน่ะ"
L38_1.m_Talk_THA = L39_1
L39_1 = "A-hem... Ta nói cô nên làm vài đồ uống trước."
L38_1.m_Talk_VTN = L39_1
L39_1 = "不、不是……嗯哼，我是说可以先学习制作饮料的方法。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Ä-ähem ... Ich meinte, du sollst zuerst ein paar Drinks anrichten."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Ah, euh... Commençons par t'apprendre à préparer quelques cocktails."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "GREMORY_ACT1_INTERLUDE1@189#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 189
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3800104
L39_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L39_1.m_Pos = "R"
L40_1 = "그래도 괜찮은 건가요? 신입 바텐더는 허드렛일부터 시작하는 줄 알았는데요."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "いいんですか？　新人バーテンダーは雑務から始まるのだと思っていました。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Are you sure? I thought new bartenders were supposed to do chores in the beginning."
L39_1.m_Talk_ENG = L40_1
L40_1 = "這樣沒關係嗎？我以為菜鳥調酒師都是從打雜開始的。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "แน่ใจเหรอคะ? ฉันนึกว่าบาร์เทนเดอร์ต้องเริ่มจากการทำพวกงานน่าเบื่อซะอีก"
L39_1.m_Talk_THA = L40_1
L40_1 = "Cô có chắc không? Tôi nghĩ những nhân viên pha chế mới ban đầu phải làm việc vặt."
L39_1.m_Talk_VTN = L40_1
L40_1 = "这样没关系吗？我听说新人调酒师会从干杂活开始。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Bist du dir sicher? Ich dachte, neue Barkeeper müssten am Anfang kleinere Aufgaben übernehmen."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Oh, vraiment ? Les nouvelles recrues comme moi ne sont-elles pas plutôt chargées de corvées, en général ?"
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "GREMORY_ACT1_INTERLUDE1@190#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 190
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 3800104
L40_1.m_CutScenStrID = "GREMORY_ACT1_INTERLUDE1"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "UNIT_HATE"
L40_1.m_Face = L41_1
L41_1 = "MOMO_BAR_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "L"
L41_1 = "m_Crash"
L42_1 = 30
L40_1[L41_1] = L42_1
L41_1 = "수, 순서는 내 마음이야! 그러니까 칼부터 내려놔!"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "じゅ、順番は吾輩が決めるのだ！　だからその包丁はしまっておけ！"
L40_1.m_Talk_JPN = L41_1
L41_1 = "I-I get to decide that! So, put down your knife!"
L40_1.m_Talk_ENG = L41_1
L41_1 = "呃…我叫你學什麼你就學什麼！先把刀放下吧！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ขะ-ข้าจะตัดสินใจเอง! ดังนั้น วางมีดลงซะ!"
L40_1.m_Talk_THA = L41_1
L41_1 = "T-ta là người quyết định việc đó! Nên là đặt con dao xuống!"
L40_1.m_Talk_VTN = L41_1
L41_1 = "顺、顺序完全看我的心情！所以先把刀放下！"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Das darf ich entscheiden! Also leg dein Messer weg!"
L40_1.m_Talk_DEU = L41_1
L41_1 = "C-C'est moi qui décide, ici ! Alors pose ce couteau et suis-moi !"
L40_1.m_Talk_FRA = L41_1
